get_customer_portal.code:
final response = await client.customerPortal.getCustomerPortal();
final customerPortal = (response.map as Map)['customer_portal'] as Map;
print(customerPortal['portal']);
print(customerPortal['login']);

patch_customer_portal.code:
final response = await client.customerPortal.patchCustomerPortal({
  'customer_portal': {
    'login': {'registration_link': false},
    'sso': {
      'azure_ad': {
        'data_mapping': {'city': 'city'},
      },
    },
  },
});
final customerPortal = (response.map as Map)['customer_portal'] as Map;
print('${customerPortal['login']} ${customerPortal['sso']}');

